package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * The settings on each sheet, by key; a key without a row is blank. A dated setting (see {@link Setting#isDated}) keeps
 * every value saved, each from its from-date; the one in force on a date is the latest from on or before it (see
 * {@link DatedSettings}).
 */
@Repository
public class SettingRepository {

    private static final RowMapper<Setting> ROW = (rs, n) -> new Setting(rs.getString("sheet_id"),
            rs.getString("setting_key"), rs.getString("setting_value"), null);

    private static final RowMapper<DatedValue> DATED = (rs, n) -> new DatedValue(rs.getString("setting_key"),
            rs.getObject("from_date", LocalDate.class), rs.getString("setting_value"));

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's undated settings, by key (the policy date, period numbering from, the grace days and the permissions); a key without a row is not listed. */
    public List<Setting> listUndated(String sheetId) {
        return jdbc.query("SELECT sheet_id, setting_key, setting_value FROM sheet_setting WHERE sheet_id = ?"
                + " ORDER BY setting_key", ROW, sheetId);
    }

    /** The sheet's dated settings: every value recorded, by key and from-date. */
    public DatedSettings dated(String sheetId) {
        return new DatedSettings(jdbc.query("SELECT setting_key, from_date, setting_value FROM sheet_setting_from"
                + " WHERE sheet_id = ? ORDER BY setting_key, from_date", DATED, sheetId));
    }

    /** The undated setting's value; null when blank. */
    public String find(String sheetId, String key) {
        return jdbc.query("SELECT sheet_id, setting_key, setting_value FROM sheet_setting WHERE sheet_id = ?"
                + " AND setting_key = ?", ROW, sheetId, key).stream().findFirst().map(Setting::value).orElse(null);
    }

    /** Whether the role may take the action (open, settle, void, reassign, close, reopen): its permission's roles, else the standing rule. */
    public boolean allows(String sheetId, String action, String role) {
        String value = find(sheetId, Setting.PERMISSION + action);
        List<String> roles = value == null ? Setting.PERMISSION_STANDING.get(action) : List.of(value.split(","));
        return roles.contains(role);
    }

    /** A person's due-total held to the cap: the cap when it is above it; n/a (null) and no cap leave it as it is. */
    public static BigDecimal capped(BigDecimal dueTotal, BigDecimal cap) {
        return dueTotal == null || cap == null || dueTotal.compareTo(cap) <= 0 ? dueTotal : cap;
    }

    /** The sheet's policy date: the one set, else its today. */
    public LocalDate policyDate(String sheetId, LocalDate today) {
        String value = find(sheetId, Setting.POLICY_DATE);
        return value == null ? today : LocalDate.parse(value);
    }

    /** The sheet's period numbering from-date; null while off. */
    public LocalDate periodNumberingFrom(String sheetId) {
        String value = find(sheetId, Setting.PERIOD_NUMBERING_FROM);
        return value == null ? null : LocalDate.parse(value);
    }

    /** The sheet's grace days; null while off. */
    public Integer graceDays(String sheetId) {
        String value = find(sheetId, Setting.GRACE_DAYS);
        return value == null ? null : Integer.valueOf(value);
    }

    /** The sheet's late charge as of its today, each 30-day boundary's late percent the one in force on its date, with its policy date for rounding. */
    public LateCharge lateCharge(String sheetId, LocalDate today) {
        return new LateCharge(today, dated(sheetId), policyDate(sheetId, today));
    }

    /** Set an undated setting's value (null: blank), replacing the one there before. */
    public Setting set(String sheetId, String key, String value) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, setting_key, setting_value) KEY (sheet_id, setting_key)"
                + " VALUES (?, ?, ?)", sheetId, key, value);
        return new Setting(sheetId, key, value, null);
    }

    /** Record a dated setting's value (null: blank) from the date, keeping the others; one already from that date is replaced. */
    public void setFrom(String sheetId, String key, LocalDate from, String value) {
        jdbc.update("MERGE INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value)"
                + " KEY (sheet_id, setting_key, from_date) VALUES (?, ?, ?, ?)", sheetId, key, from, value);
    }

    /** Every setting as of the date: each dated key's value in force then (its starting value, or blank), and the undated ones set. */
    public List<SettingResponse> listOn(String sheetId, LocalDate today) {
        DatedSettings dated = dated(sheetId);
        List<SettingResponse> found = new ArrayList<>();
        java.util.Set<String> keys = new java.util.TreeSet<>(List.of(Setting.FLOOR, Setting.TERMS, Setting.LATE_PCT));
        dated.values().forEach(v -> keys.add(v.key()));
        for (String key : keys) {
            found.add(new SettingResponse(key, dated.on(key, today), dated.values().stream()
                    .filter(v -> v.key().equals(key))
                    .map(v -> new SettingResponse.From(v.from().toString(), v.value())).toList()));
        }
        listUndated(sheetId).forEach(s -> found.add(new SettingResponse(s.key(), s.value(), List.of())));
        return found;
    }
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.claim.Claim;

/**
 * The late charge as of the sheet's today: an OPEN (or PENDING) claim past its due-by (fixed when it was added) gains, for every
 * full 30 days it is overdue, the late percent in force on that boundary date (the due-by plus 30, 60, 90 ... days) of its figure,
 * each rounded to two decimals as the claim rounds (see {@link #rounding}), the charges added up. A correction
 * (a negative amount) never gains one. The charge is never bound by a statement; settling freezes it into the settled due.
 * The floor is applied last: a claim's live due is the greater of the floor in force on its date and its figure plus its
 * late charge (a correction has no floor).
 */
public record LateCharge(LocalDate today, DatedSettings settings, LocalDate policyDate) {

    /**
     * How the claim's live figures round: half up when it is dated before the policy date, half to even on or after
     * it. A correction rounds by the date of the claim it corrects.
     */
    public RoundingMode rounding(Claim claim) {
        return claim.getRoundOn().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The claim's late charge on its figure (zero when it is not overdue, is deferred past today, or has no figure). */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (!claim.getStatus().isOpen() || claim.isDeferredOn(today)) {
            return none;
        }
        return onAsOpen(claim, figure);
    }

    /** The late charge the claim would have on its figure were it OPEN. */
    public BigDecimal onAsOpen(Claim claim, BigDecimal figure) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (figure == null || claim.isCorrection()) {
            return none;
        }
        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
        long periods = overdue > 0 ? overdue / 30 : 0;
        if (periods == 0) {
            return none;
        }
        BigDecimal charge = none;
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = settings.latePct(claim.getDueBy().plusDays(30 * n));
            if (pct.signum() != 0) {
                charge = charge.add(figure.multiply(pct).movePointLeft(2).setScale(2, rounding(claim)));
            }
        }
        return charge;
    }

    /**
     * The claim's due: its settled due as it is; else the greater of the floor in force on its date and the figure with
     * its late charge added on top (a correction has no floor); null without a figure.
     */
    public BigDecimal due(Claim claim, BigDecimal figure) {
        if (figure == null) {
            return null;
        }
        if (claim.getSettledDue() != null) {
            return figure.setScale(2);
        }
        return floored(claim, figure.setScale(2).add(on(claim, figure)));
    }

    /** The due the claim would have were it OPEN (floored as {@link #due}); null without a figure. */
    public BigDecimal dueAsOpen(Claim claim, BigDecimal figure) {
        return figure == null ? null : floored(claim, figure.setScale(2).add(onAsOpen(claim, figure)));
    }

    /** At least the floor in force on the claim's date, unless it is a correction. */
    private BigDecimal floored(Claim claim, BigDecimal due) {
        return claim.isCorrection() ? due : due.max(settings.floor(claim.getDate()));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.BadRequestException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheets: a row per id ever loaded. */
@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Create the sheet if its id was never used (its today the real date); an existing sheet is left as it is. */
    public void ensure(String id) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) SELECT ?, COALESCE((SELECT today FROM sheet WHERE id = ?), ?)",
                id, id, LocalDate.now());
    }

    /**
     * The sheet's today. Every decision that depends on the date, and every default date, uses
     * this — never the real clock. A sheet not yet stored is on the real date.
     */
    public LocalDate today(String id) {
        return jdbc.query("SELECT today FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : LocalDate.now(), id);
    }

    public void setToday(String id, LocalDate today) {
        jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", today, id);
    }

    /** Whether the sheet is archived: then every change to it is refused. A sheet not yet stored is not. */
    public boolean isArchived(String id) {
        return jdbc.query("SELECT archived FROM sheet WHERE id = ?", rs -> rs.next() && rs.getBoolean(1), id);
    }

    /** Refuse a change to the sheet while it is archived. */
    public void refuseArchived(String id) throws BadRequestException {
        if (isArchived(id)) {
            throw new BadRequestException("This sheet is archived");
        }
    }

    public void archive(String id) {
        jdbc.update("UPDATE sheet SET archived = TRUE WHERE id = ?", id);
    }
}
