package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Takes the sheet's figures before the change writes anything, so RecordRollup can tell what it moved. */
public class SnapshotRollup {
    public void snapshot(@Val SheetResponse sheet, Rollup rollup, Out<RollupBefore> before) {
        before.set(new RollupBefore(rollup.snapshot(sheet.id())));
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;

public class EnsureSheet {
    public void ensure(@Val SheetResponse sheet, SheetRepository repository) {
        repository.ensure(sheet.id());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;

/** A person on a sheet. Mutable so an Apply step can change it in place. */
public class Person {

    private final long id;
    private final String sheetId;
    private String name;
    private String grade;
    private List<GradeFrom> grades = List.of();
    private long version;
    private Statements statements = Statements.NONE;
    private LocalDate retiredFrom;
    private List<HoldSpan> holds = List.of();
    private List<String> patrons = List.of();
    private Integer terms;

    public Person(long id, String sheetId, String name, String grade, long version) {
